function loadFile(file) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => { _image = img; sBus.publish('org:image_loaded', { w: img.naturalWidth, h: img.naturalHeight }); resolve(img); };
    img.onerror = reject;
    img.src = url;
  });
}
